//! The values of the satellite protocol `nestor.satellite/1`: a device, what it can do, how it can
//! be paired, and the intents it receives.
//!
//! They mirror the JSON Schemas vendored in `schemas/`, generated by the Nestor server: every
//! constructor checks the same constraints, so a manifest built here is one the core accepts.

use std::collections::BTreeSet;
use std::fmt;

use serde::{Deserialize, Serialize};
use serde_json::{Map, Value};
use thiserror::Error;

/// The protocol this SDK speaks.
pub const PROTOCOL: &str = "nestor.satellite/1";

/// The device sends what a person typed (`input.text`).
pub const TEXT_INPUT: &str = "text.input";
/// The device shows the assistant's words (`intent.text`).
pub const TEXT_DISPLAY: &str = "text.display";
/// The device captures audio (a microphone) and streams it to the core.
pub const AUDIO_CAPTURE: &str = "audio.capture";
/// The device plays the core's voice (a speaker).
pub const AUDIO_PLAYBACK: &str = "audio.playback";
/// The device performs expressions (`intent.expression`).
pub const EXPRESSION: &str = "expression.emotion";
/// The device moves its head with speech (`intent.beat`).
pub const HEAD_MOTION: &str = "motion.head";
/// The device detects people on its own (`observation.person.detected`).
pub const PERSON_DETECTION: &str = "vision.person_detection";
/// The device detects voice activity on its own (`observation.speech.activity`).
pub const SPEECH_ACTIVITY: &str = "audio.speech_activity";
/// The device can make itself noticed (blink, wiggle, chime) when a person asks which one it is
/// (`intent.identify`, and `identify` in a pending pairing's answer). An aid, never a proof.
pub const IDENTIFY: &str = "device.identify";
/// The device installs a newer version of its own software when a person asks (`intent.update`),
/// and reports where it stands (`update.status`). Declared when the driver gives an
/// [`Updater`](crate::Updater).
pub const UPDATE: &str = "device.update";

/// At most this many capabilities in a manifest.
pub const MAX_CAPABILITIES: usize = 32;
const MAX_TEXT: usize = 64;

/// Something that does not follow `nestor.satellite/1`.
#[derive(Debug, Clone, PartialEq, Eq, Error)]
#[error("{0}")]
pub struct ProtocolError(pub(crate) String);

impl ProtocolError {
    pub(crate) fn new(message: impl Into<String>) -> Self {
        Self(message.into())
    }
}

/// The assistant's attitude, shown until the next one.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Behavior {
    /// At rest.
    Idle,
    /// Someone is talking to the assistant.
    Listening,
    /// The assistant prepares its answer.
    Thinking,
    /// The assistant speaks.
    Speaking,
}

/// An expression, performed as the matching audio is played.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Expression {
    /// A laugh, a smile.
    Joy,
    /// A sigh.
    Sigh,
    /// Pondering.
    Thoughtful,
    /// A whisper.
    Whisper,
    /// Excitement.
    Excited,
    /// Clearing the throat.
    Ahem,
}

impl Behavior {
    /// Every behavior, in the schema's order.
    pub const ALL: [Self; 4] = [Self::Idle, Self::Listening, Self::Thinking, Self::Speaking];

    /// The wire name (`"idle"`).
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Idle => "idle",
            Self::Listening => "listening",
            Self::Thinking => "thinking",
            Self::Speaking => "speaking",
        }
    }
}

impl Expression {
    /// Every expression, in the schema's order.
    pub const ALL: [Self; 6] = [Self::Joy, Self::Sigh, Self::Thoughtful, Self::Whisper, Self::Excited, Self::Ahem];

    /// The wire name (`"joy"`).
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Joy => "joy",
            Self::Sigh => "sigh",
            Self::Thoughtful => "thoughtful",
            Self::Whisper => "whisper",
            Self::Excited => "excited",
            Self::Ahem => "ahem",
        }
    }
}

impl fmt::Display for Behavior {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.as_str())
    }
}

impl fmt::Display for Expression {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.as_str())
    }
}

/// How a person can pair a device. A manifest declares those the device can carry out.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
pub enum PairingMethod {
    /// The person reads the device code on the device's screen and types it in Nestor.
    #[serde(rename = "device_code.display")]
    DeviceCodeDisplay,
    /// The person hears the device say its code and types it in Nestor.
    #[serde(rename = "device_code.speech")]
    DeviceCodeSpeech,
    /// The person types an enrollment code on the device.
    #[serde(rename = "enrollment.input")]
    EnrollmentInput,
    /// The person sets the pairing URI or the enrollment code in the device's configuration (flag,
    /// environment, file). Every device supports it.
    #[serde(rename = "enrollment.provisioning")]
    EnrollmentProvisioning,
}

impl PairingMethod {
    /// Every method this SDK can declare, in the schema's order. The protocol's `enrollment.qr`
    /// (scanning the pairing URI's QR code) needs a camera, which this SDK does not drive: it is
    /// not one of them.
    pub const ALL: [Self; 4] =
        [Self::DeviceCodeDisplay, Self::DeviceCodeSpeech, Self::EnrollmentInput, Self::EnrollmentProvisioning];

    /// The wire name (`"device_code.display"`).
    pub fn as_str(self) -> &'static str {
        match self {
            Self::DeviceCodeDisplay => "device_code.display",
            Self::DeviceCodeSpeech => "device_code.speech",
            Self::EnrollmentInput => "enrollment.input",
            Self::EnrollmentProvisioning => "enrollment.provisioning",
        }
    }
}

impl fmt::Display for PairingMethod {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.as_str())
    }
}

/// How the device received an enrollment code: the pairing methods whose proof is an enrollment code
/// that this SDK carries out (not `enrollment.qr`: it drives no camera).
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
pub enum EnrollmentMethod {
    /// Typed on the device.
    #[serde(rename = "enrollment.input")]
    Input,
    /// Set in its configuration (flag, environment, file).
    #[serde(rename = "enrollment.provisioning")]
    Provisioning,
}

impl From<EnrollmentMethod> for PairingMethod {
    fn from(method: EnrollmentMethod) -> Self {
        match method {
            EnrollmentMethod::Input => Self::EnrollmentInput,
            EnrollmentMethod::Provisioning => Self::EnrollmentProvisioning,
        }
    }
}

impl fmt::Display for EnrollmentMethod {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        PairingMethod::from(*self).fmt(f)
    }
}

/// A device. `id`, `room` and `brand` are lowercase slugs: they end up in addresses (`voice:salon`).
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct Device {
    id: String,
    model: String,
    room: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    brand: Option<String>,
}

impl Device {
    /// A device `id` (`enceinte-salon`) of a `model` (`raspberry-pi-4`) in a `room` (`salon`).
    pub fn new(
        id: impl Into<String>,
        model: impl Into<String>,
        room: impl Into<String>,
    ) -> Result<Self, ProtocolError> {
        let (id, model, room) = (id.into(), model.into(), room.into());
        for (name, value) in [("id", &id), ("room", &room)] {
            if !is_slug(value) {
                return Err(ProtocolError::new(format!(
                    "device {name} {value:?} must be a lowercase slug (a-z, 0-9, - and _)"
                )));
            }
        }
        if model.is_empty() || model.chars().count() > MAX_TEXT {
            return Err(ProtocolError::new("device model must be 1 to 64 characters"));
        }
        Ok(Self { id, model, room, brand: None })
    }

    /// Its maker, as a slug (`pollen-robotics`).
    pub fn with_brand(mut self, brand: impl Into<String>) -> Result<Self, ProtocolError> {
        let brand = brand.into();
        if !is_slug(&brand) {
            return Err(ProtocolError::new(format!(
                "device brand {brand:?} must be a lowercase slug (a-z, 0-9, - and _)"
            )));
        }
        self.brand = Some(brand);
        Ok(self)
    }

    /// The device id, unique in the household.
    pub fn id(&self) -> &str {
        &self.id
    }

    /// The device model.
    pub fn model(&self) -> &str {
        &self.model
    }

    /// The room the device is in.
    pub fn room(&self) -> &str {
        &self.room
    }

    /// The device's maker, when declared.
    pub fn brand(&self) -> Option<&str> {
        self.brand.as_deref()
    }
}

/// The software a device runs, named as its package is where it is installed from (`nestor-satellite`
/// `0.5.2`). A device that updates itself installs newer versions of this package.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct Software {
    name: String,
    version: String,
}

impl Software {
    /// A software name and version, each 1 to 64 characters.
    pub fn new(name: impl Into<String>, version: impl Into<String>) -> Result<Self, ProtocolError> {
        let (name, version) = (name.into(), version.into());
        for (key, value) in [("name", &name), ("version", &version)] {
            if value.is_empty() || value.chars().count() > MAX_TEXT {
                return Err(ProtocolError::new(format!("software {key} must be 1 to 64 characters")));
            }
        }
        Ok(Self { name, version })
    }

    /// This crate: `nestor-satellite` and its version.
    pub fn this() -> Self {
        Self { name: env!("CARGO_PKG_NAME").to_owned(), version: env!("CARGO_PKG_VERSION").to_owned() }
    }

    /// The software name.
    pub fn name(&self) -> &str {
        &self.name
    }

    /// The software version.
    pub fn version(&self) -> &str {
        &self.version
    }
}

/// A capability the device declares (`family.feature`), with its own parameters.
#[derive(Debug, Clone, PartialEq)]
pub struct Capability {
    name: String,
    params: Map<String, Value>,
}

impl Capability {
    /// A capability by name, e.g. [`AUDIO_CAPTURE`].
    pub fn new(name: impl Into<String>) -> Result<Self, ProtocolError> {
        let name = name.into();
        if !is_capability(&name) {
            return Err(ProtocolError::new(format!("invalid capability {name:?}: expected 'family.feature'")));
        }
        Ok(Self { name, params: Map::new() })
    }

    /// Adds a parameter, e.g. `("formats", json!(["opus/48000"]))`; `name` is reserved.
    pub fn with_param(mut self, key: impl Into<String>, value: impl Into<Value>) -> Result<Self, ProtocolError> {
        let key = key.into();
        if key == "name" {
            return Err(ProtocolError::new("a capability parameter cannot be called 'name'"));
        }
        self.params.insert(key, value.into());
        Ok(self)
    }

    /// The capability name.
    pub fn name(&self) -> &str {
        &self.name
    }

    /// Its parameters.
    pub fn params(&self) -> &Map<String, Value> {
        &self.params
    }
}

impl Serialize for Capability {
    fn serialize<S: serde::Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
        let mut entry = Map::with_capacity(self.params.len() + 1);
        entry.insert("name".to_owned(), Value::String(self.name.clone()));
        entry.extend(self.params.clone());
        entry.serialize(serializer)
    }
}

/// What a device says about itself when it pairs and when it connects.
///
/// It declares [`PairingMethod::EnrollmentProvisioning`] only; a [`Satellite`](crate::Satellite)
/// replaces its pairing methods with those its outputs and inputs carry out.
#[derive(Debug, Clone, PartialEq)]
pub struct Manifest {
    device: Device,
    capabilities: Vec<Capability>,
    software: Software,
    pairing_methods: BTreeSet<PairingMethod>,
}

impl Manifest {
    /// A manifest declaring capabilities by name; it names this crate ([`Software::this`]).
    pub fn new<I, S>(device: Device, capabilities: I) -> Result<Self, ProtocolError>
    where
        I: IntoIterator<Item = S>,
        S: Into<String>,
    {
        let capabilities = capabilities.into_iter().map(Capability::new).collect::<Result<Vec<_>, _>>()?;
        Self::with_capabilities(device, capabilities)
    }

    /// A manifest declaring capabilities with parameters; it names this crate ([`Software::this`]).
    pub fn with_capabilities(device: Device, capabilities: Vec<Capability>) -> Result<Self, ProtocolError> {
        if capabilities.len() > MAX_CAPABILITIES {
            return Err(ProtocolError::new(format!("at most {MAX_CAPABILITIES} capabilities")));
        }
        let names: BTreeSet<&str> = capabilities.iter().map(Capability::name).collect();
        if names.len() != capabilities.len() {
            return Err(ProtocolError::new("a capability is declared twice"));
        }
        Ok(Self {
            device,
            capabilities,
            software: Software::this(),
            pairing_methods: BTreeSet::from([PairingMethod::EnrollmentProvisioning]),
        })
    }

    /// Declares the pairing methods the device carries out: at least one.
    pub fn with_pairing_methods(
        mut self,
        methods: impl IntoIterator<Item = PairingMethod>,
    ) -> Result<Self, ProtocolError> {
        let methods: BTreeSet<PairingMethod> = methods.into_iter().collect();
        if methods.is_empty() {
            return Err(ProtocolError::new("a manifest declares at least one pairing method"));
        }
        self.pairing_methods = methods;
        Ok(self)
    }

    /// The manifest with these capabilities declared too (those already declared are kept as they are).
    pub(crate) fn declaring<'a>(mut self, names: impl IntoIterator<Item = &'a str>) -> Result<Self, ProtocolError> {
        for name in names {
            if !self.declares(name) {
                self.capabilities.push(Capability::new(name)?);
            }
        }
        if self.capabilities.len() > MAX_CAPABILITIES {
            return Err(ProtocolError::new(format!("at most {MAX_CAPABILITIES} capabilities")));
        }
        Ok(self)
    }

    /// Names the software the device runs, when it is not this crate's command: a driver names its
    /// own package, the one an [`Updater`](crate::Updater) installs.
    pub fn with_software(mut self, software: Software) -> Self {
        self.software = software;
        self
    }

    /// The device.
    pub fn device(&self) -> &Device {
        &self.device
    }

    /// The declared capabilities.
    pub fn capabilities(&self) -> &[Capability] {
        &self.capabilities
    }

    /// The software the device runs.
    pub fn software(&self) -> &Software {
        &self.software
    }

    /// The declared pairing methods, in the schema's order.
    pub fn pairing_methods(&self) -> impl Iterator<Item = PairingMethod> + '_ {
        self.pairing_methods.iter().copied()
    }

    /// Whether the pairing method is declared.
    pub fn supports(&self, method: PairingMethod) -> bool {
        self.pairing_methods.contains(&method)
    }

    /// Whether the capability `name` is declared.
    pub fn declares(&self, name: &str) -> bool {
        self.capabilities.iter().any(|c| c.name == name)
    }

    /// The manifest as the core reads it (`manifest.json`).
    pub fn to_json(&self) -> Value {
        let mut data = Map::new();
        data.insert("protocol".to_owned(), Value::String(PROTOCOL.to_owned()));
        data.insert("device".to_owned(), to_value(&self.device));
        data.insert("capabilities".to_owned(), Value::Array(self.capabilities.iter().map(to_value).collect()));
        data.insert("software".to_owned(), to_value(&self.software));
        let methods = self.pairing_methods.iter().map(|m| Value::String(m.as_str().to_owned())).collect();
        data.insert("pairing_methods".to_owned(), Value::Array(methods));
        Value::Object(data)
    }
}

fn to_value(value: &impl Serialize) -> Value {
    // Only maps of strings and JSON values are serialized here: this cannot fail.
    serde_json::to_value(value).unwrap_or(Value::Null)
}

/// `^[a-z0-9][a-z0-9_-]{0,63}$`
pub(crate) fn is_slug(value: &str) -> bool {
    let mut chars = value.chars();
    let first_ok = chars.next().is_some_and(|c| c.is_ascii_lowercase() || c.is_ascii_digit());
    first_ok
        && value.len() <= MAX_TEXT
        && chars.all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '_' || c == '-')
}

/// `^[a-z][a-z0-9_]*(\.[a-z][a-z0-9_]*)+$`
fn is_capability(value: &str) -> bool {
    let parts: Vec<&str> = value.split('.').collect();
    parts.len() >= 2
        && parts.iter().all(|part| {
            let mut chars = part.chars();
            chars.next().is_some_and(|c| c.is_ascii_lowercase())
                && chars.all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '_')
        })
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    fn device() -> Device {
        Device::new("enceinte-salon", "raspberry-pi-4", "salon").unwrap()
    }

    #[test]
    fn a_device_id_and_room_must_be_lowercase_slugs() {
        assert!(Device::new("Salon", "m", "salon").is_err());
        assert!(Device::new("ok", "m", "sa lon").is_err());
        assert!(Device::new("-x", "m", "salon").is_err());
        assert!(Device::new("x".repeat(65), "m", "salon").is_err());
        assert!(Device::new("x".repeat(64), "m", "salon").is_ok());
        assert!(device().with_brand("Pollen").is_err());
    }

    #[test]
    fn a_device_model_has_one_to_64_characters() {
        assert!(Device::new("a", "", "salon").is_err());
        assert!(Device::new("a", "é".repeat(64), "salon").is_ok());
        assert!(Device::new("a", "m".repeat(65), "salon").is_err());
    }

    #[test]
    fn a_capability_is_a_dotted_family_and_feature() {
        assert!(Capability::new("audio.capture").is_ok());
        assert!(Capability::new("vision.person_detection").is_ok());
        for wrong in ["audio", "Audio.capture", "audio.", ".capture", "audio.1x", "a..b"] {
            assert!(Capability::new(wrong).is_err(), "{wrong}");
        }
        assert!(Capability::new("audio.capture").unwrap().with_param("name", 1).is_err());
    }

    #[test]
    fn a_manifest_refuses_duplicates_and_too_many_capabilities() {
        assert!(Manifest::new(device(), [AUDIO_CAPTURE, AUDIO_CAPTURE]).is_err());
        let many: Vec<String> = (0..33).map(|i| format!("custom.f{i}")).collect();
        assert!(Manifest::new(device(), many).is_err());
    }

    #[test]
    fn a_manifest_serializes_as_the_core_reads_it() {
        let capture = Capability::new(AUDIO_CAPTURE).unwrap().with_param("formats", json!(["opus/48000"])).unwrap();
        let manifest = Manifest::with_capabilities(device().with_brand("raspberry").unwrap(), vec![capture]).unwrap();
        assert_eq!(
            manifest.to_json(),
            json!({
                "protocol": "nestor.satellite/1",
                "device": {"id": "enceinte-salon", "model": "raspberry-pi-4", "room": "salon", "brand": "raspberry"},
                "capabilities": [{"name": "audio.capture", "formats": ["opus/48000"]}],
                "software": {"name": "nestor-satellite", "version": env!("CARGO_PKG_VERSION")},
                "pairing_methods": ["enrollment.provisioning"],
            })
        );
        assert!(manifest.declares(AUDIO_CAPTURE) && !manifest.declares(AUDIO_PLAYBACK));
        let driver = Software::new("nestor-reachy", "0.4.0").unwrap();
        let bare = Manifest::new(device(), [AUDIO_PLAYBACK]).unwrap().with_software(driver);
        assert_eq!(bare.to_json()["software"], json!({"name": "nestor-reachy", "version": "0.4.0"}));
        assert!(bare.to_json()["device"].get("brand").is_none());
        assert!(Software::new("", "1.0.0").is_err() && Software::new("x", "1".repeat(65)).is_err());
    }

    #[test]
    fn pairing_methods_are_declared_once_each_in_the_schema_s_order() {
        use PairingMethod::*;
        let manifest = Manifest::new(device(), [IDENTIFY]).unwrap();
        assert!(manifest.with_pairing_methods([]).is_err(), "at least one");
        let manifest = Manifest::new(device(), [IDENTIFY])
            .unwrap()
            .with_pairing_methods([EnrollmentProvisioning, DeviceCodeSpeech, DeviceCodeDisplay, DeviceCodeSpeech])
            .unwrap();
        assert_eq!(
            manifest.to_json()["pairing_methods"],
            json!(["device_code.display", "device_code.speech", "enrollment.provisioning"])
        );
        assert!(manifest.supports(DeviceCodeSpeech) && !manifest.supports(EnrollmentInput));
        let names: Vec<&str> = PairingMethod::ALL.iter().map(|m| m.as_str()).collect();
        assert_eq!(serde_json::to_value(PairingMethod::ALL).unwrap(), json!(names));
        assert_eq!(PairingMethod::from(EnrollmentMethod::Input), EnrollmentInput);
    }
}
